BOOL dMap_isBossDoor(stage_tgsc_data_class* i_stage) {
    if (strcmp(i_stage->name, "door20") == 0) {
        return TRUE;
    }
    if (strcmp(i_stage->name, "door12") == 0) {
        switch (i_stage->base.angle.z >> 8 & 0xFF) {
            case 12:
            case 9:
                return TRUE;
        }
    }
    return FALSE;
}

